import{_ as a,a0 as s,w as p,s as u,I as i,x as t,a1 as n,A as r,ao as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"在開源“集市”工作時如何建立一個職業網絡 | LCTT x X-CMD","titleTemplate":false,"description":"在開源“集市”工作時如何建立一個職業網絡 | LCTT (201809) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在開源“集市”工作時如何建立一個職業網絡 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在開源“集市”工作時如何建立一個職業網絡 | LCTT (201809) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201809/20180626 How to build a professional network when you work in a bazaar","title":"在開源“集市”工作時如何建立一個職業網絡","tag":"201809","desc":""},"relativePath":"201809/20180626 How to build a professional network when you work in a bazaar.md","filePath":"[post].md"}'),d={name:"201809/20180626 How to build a professional network when you work in a bazaar.md"};function f(m,l,b,T,w,g){const o=s("Link");return p(),u("div",null,[l[29]||(l[29]=i("h1",{id:"在開源-集市-工作時如何建立一個職業網絡",tabindex:"-1"},[t("在開源“集市”工作時如何建立一個職業網絡 "),i("a",{class:"header-anchor",href:"#在開源-集市-工作時如何建立一個職業網絡","aria-label":"Permalink to “在開源“集市”工作時如何建立一個職業網絡”"},"​")],-1)),l[30]||(l[30]=i("blockquote",null,[i("p",null,"在組織內建立聯繫遇到問題了嗎？你或許是採用了錯誤的策略。")],-1)),l[31]||(l[31]=i("p",null,[i("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/connection_people_team_collaboration.png?itok=0_vQT8xV",alt:""})],-1)),l[32]||(l[32]=i("p",null,"職業社交網絡 —— 在同事或專業人員之間建立人際聯繫 —— 可以採用多種形式、在產業內跨組織進行。建立職業網絡需要花費時間和精力，並且當某位成員加入或離開一個組織時，此人的網絡通常需要被在一個新的工作環境中重建。",-1)),l[33]||(l[33]=i("p",null,[t("職業社交網絡在不同組織中起相似作用 —— 信息共享、導師制、機會、工作利益和其他作用 —— 然而傳統組織與開放組織在組織內構建特定聯繫的"),i("em",null,"方法"),t("和"),i("em",null,"原因"),t("可能不盡相同。這些差異有其影響：同事聯繫方式、如何建立信任、組織內多元化的程度和種類以及建立合作的能力，所有這些因素都是相互關聯的，而且它們參與並塑造了人們所建立的社交網絡。")],-1)),i("p",null,[l[2]||(l[2]=t("一個開放的組織對包容性的強調可以使社交網絡在解決商業問題上比傳統等級制組織更加高效。這種觀念在開源的思考中有很久的歷史。例如，在",-1)),i("ruby",null,[n(o,{href:"http://www.catb.org/~esr/writings/cathedral-bazaar/cathedral-bazaar/ar01s04.html"},{default:r(()=>[...l[0]||(l[0]=[t("《教堂與集市》",-1)])]),_:1}),l[1]||(l[1]=i("rt",null,"The Cathedral and the Bazaar",-1))]),l[3]||(l[3]=t("中，埃裏克·雷蒙德寫道：“許多年前社會學家發現，相比一個隨機選擇的觀察者的觀點，許多同等專業的（或是同等無知的）觀察家的普遍觀點是可靠得多的預言。”所以讓我們瞭解社交網絡的結構和目的如何影響各類組織的價值觀。",-1))]),l[34]||(l[34]=e('<h3 id="傳統組織中的社交網絡" tabindex="-1">傳統組織中的社交網絡 <a class="header-anchor" href="#傳統組織中的社交網絡" aria-label="Permalink to “傳統組織中的社交網絡”">​</a></h3><p>當我在傳統組織工作並要描述我為工作做了什麼時，人們問我的第一件事就是我與其他人（通常是總監級的領導）的關係。“你在希拉手下嗎？”他們會這麼問。“你為馬爾科姆工作嗎？”這意味着以一種上下級的視角看待傳統組織的作用；當試圖安排工作或僱員時，人們想要從上下級的角度理解網絡結構。</p><p>換言之，在傳統組織中社交網絡依賴於等級制結構，因此他們彼此跟隨。事實上，甚至弄清一個僱員在關係網中處於怎樣的位置也算得上是一種“上下級組織”式的擔憂。</p><p>然而並非所有潛在等級制都是如此。它還視相關人員而定。對於上下級網絡的關注會決定僱員在網絡中的“價值”，因為網絡本身是一個持續的權力關係的系統，它會根據人不同水平的價值給予他們不同的定位。它淡化了個人的能力和技能的重要性。因此，一個人在傳統組織的聯繫促使其能力具有前瞻性，為人所知，有影響力並在其事業中起到支持作用。</p><p>相比傳統等級制組織，一個開放的組織對包容性的強調能使網絡解決商業問題更加高效。</p><p>傳統組織的正式結構以特定方式決定着僱員的社交網絡 —— 有些可能是優點，有些可能是缺點，這取決於具體環境——例如：</p><ul><li>要更快速地瞭解“誰是誰”並看到人們如何關聯是較為便捷的（通常這在特定層級內建立信任網絡）。</li><li>通常，這種對關係的進一步的理解意味着會有更少的過剩工作（在一個特定網絡中項目有清晰的相應的歸屬者）和過多交流（人們知道誰對交流什麼負責）。</li><li>相關人員會感到在一個權力結構中感到束手無策，或好像他們不能“闖入”權力結構中，這些結構有時（或更多時候）因為裁員並不起作用。</li><li>完成大量的工作和努力是困難的，並且合作會很艱難。</li><li>權力轉讓緩慢；一個人的參與能力更多地決定於等級結構所創造的網絡的結盟而非其他因素（比如個人能力），減少了被看做社區和成員利益的東西。</li><li>競爭似乎更加清晰；理解“誰在競爭什麼”通常發生在一個公認的、被限定了的等級結構中（權力網絡中職位的缺乏增進了競爭因此競爭會更激烈）。</li><li>當更嚴格的網絡決定了靈活性的限度時，適應能力會受損。網絡的“夙願”和合作的限度也會以同樣的方式受影響。</li><li>在嚴格的網絡中，方向明確，並且領導人通常靠過度指導來進行管理，在這裏，破壞更容易發生。</li><li>當社交網絡不那麼靈活時，風險下降；人們知道什麼需要發生，怎樣發生，何時發生（但是考慮到在一個組織中工作的廣度，這不見得總是“壞事”；一些工作的職能需要較小的風險，例如：人力資源管理 HR）,企業併購和法律工作等。</li><li>在網絡中的信任是更大的，尤其當受僱者是正式網絡的一部分的時候（當某人不是網絡的一份子時，被排斥的人可能特別難管理或改正）。</li></ul><h3 id="開放組織中的社交網絡" tabindex="-1">開放組織中的社交網絡 <a class="header-anchor" href="#開放組織中的社交網絡" aria-label="Permalink to “開放組織中的社交網絡”">​</a></h3><p>儘管開放組織必定會有等級結構，但他們並不根據那個網絡運作。他們的職業網絡結構更加靈活（或者説是“隨時隨地”）。</p><p>在一個開放的組織中，當我描述我做了什麼工作時，幾乎沒人問我“我為誰而幹？”一個開放的組織更多的以夥伴為中心，而不是以領導為中心。開放的價值觀比如包容和特定的治理系統比如強人治理有助於此；那並不是你瞭解誰而是你瞭解什麼，你怎樣使用（比如：“自底而上的設計”）。在一個開放的組織當中，我並不感覺我在為展示自己的價值而奮鬥；我的想法有內在的價值。有時我必須示範説明為何使用我的觀點比使用別人的更加有用——但是那意味着我正在同事的社區裏面診療我自己（包括領導層），而不是單獨被自上而下的領導層診療。</p><p>如此説來，開放的組織並不基於網絡評估員工，而是基於他們對作為個人的同事的瞭解。這個人有想法嗎？她會努力通過利用開放組織的價值實現那些想法嗎（領導它們）(也就是説，在開放組織中分享那些觀點並且實踐以將他人囊括並透明公開的工作等等)？</p><p>開放組織也會以特定的方式構造社交網絡（這種方式同樣可能會視個人的目的性和渴望程度而很有益或很有害），這包括：</p>',12)),i("ul",null,[l[7]||(l[7]=i("li",null,"人們會對他們的網絡、聲望、技能和事業更加負責。",-1)),l[8]||(l[8]=i("li",null,"競爭(為了資源、權力、晉升等)會因這些組織天性更具合作性而變得更少。最好的結果是協商，而不是單贏，並且競爭會磨練創意，而不會在人與人之間築籬設笆。",-1)),i("li",null,[l[5]||(l[5]=t("權力是更加流動和有活力的，在人與人之間流動（但這同時也意味着可能有對可説明性或者責任的誤解，而且活動可能會因為沒有明晰的",-1)),n(o,{href:"https://opensource.com/open-organization/18/4/rethinking-ownership-across-organization"},{default:r(()=>[...l[4]||(l[4]=[t("主人翁意識",-1)])]),_:1}),l[6]||(l[6]=t("而不被完成）。",-1))]),l[9]||(l[9]=i("li",null,"信任是“一次一同事”地被建立起來的而不會藉助社交網絡，在網絡中，人是被定位着的。",-1)),l[10]||(l[10]=i("li",null,"網絡在多樣的運轉和事件中會自配置，一有機會便會反應性地自啓（這幫助了更新但卻會造成混亂，因為誰在決策、誰在“受控”是不那麼明確的）。",-1)),l[11]||(l[11]=i("li",null,"執行速度在混亂的環境中會下降，因為所做之事、做事方式和處事時間需要在制定目標和涵養好整以暇的員工方面上的領導力。",-1)),l[12]||(l[12]=i("li",null,"靈活的社交網絡同樣會增加變革和風險；創意會流通得更快而且更神奇，並且執行會更加自信。",-1)),l[13]||(l[13]=i("li",null,"信任建立在同事合作之上（它本該如此！），而不是在對架構的尊重之上。",-1))]),l[35]||(l[35]=e('<h3 id="讓它有效" tabindex="-1">讓它有效 <a class="header-anchor" href="#讓它有效" aria-label="Permalink to “讓它有效”">​</a></h3><p>如果你正在考慮從一種組織架構轉變為另一種，當你在構建並維持你的職業社交網絡時思考一下如下所述內容。</p><h4 id="來自傳統組織的小建議" tabindex="-1">來自傳統組織的小建議 <a class="header-anchor" href="#來自傳統組織的小建議" aria-label="Permalink to “來自傳統組織的小建議”">​</a></h4><ul><li>對決策的架構和管控不是壞事；運作中的框架需要明晰透明，而且決策者需要考慮他們的決定。</li><li>在執行上突出需要經理提供關注，還需要有在濾出任何讓人分心或混亂的事務的同時仍能提供足夠的來龍去脈的能力。</li><li>已經確立的網絡幫助了一大批人同步工作並且能管控風險。</li></ul><h4 id="來自開放組織的小建議" tabindex="-1">來自開放組織的小建議 <a class="header-anchor" href="#來自開放組織的小建議" aria-label="Permalink to “來自開放組織的小建議”">​</a></h4><ul><li>能力強的領導人是那些可以根據多樣的風格和對同事、團隊的不同偏好提供不同層次的透明度和指導，同時又不會構建出不靈活的網絡的人。</li><li>偉大的想法比已建立的組織會贏得更多。</li><li>人們對他們的名聲會更加負責任。</li><li>創意和信息的流轉是變革的關鍵。鬆散組織中的關係網絡可以使這兩種元素生髮的頻度更高、幅度更廣。</li></ul><hr>',7)),i("p",null,[l[15]||(l[15]=t("via: ",-1)),n(o,{href:"https://opensource.com/open-organization/18/6/building-professional-social-networks-openly"},{default:r(()=>[...l[14]||(l[14]=[t("https://opensource.com/open-organization/18/6/building-professional-social-networks-openly",-1)])]),_:1})]),i("p",null,[l[20]||(l[20]=t("作者：",-1)),n(o,{href:"https://opensource.com/users/heidi-hess-von-ludewig"},{default:r(()=>[...l[16]||(l[16]=[t("Heidi Hess von Ludewig",-1)])]),_:1}),l[21]||(l[21]=t(" 選題：",-1)),n(o,{href:"https://github.com/lujun9972"},{default:r(()=>[...l[17]||(l[17]=[t("lujun9972",-1)])]),_:1}),l[22]||(l[22]=t(" 譯者：",-1)),n(o,{href:"https://github.com/ZenMoore"},{default:r(()=>[...l[18]||(l[18]=[t("ZenMoore",-1)])]),_:1}),l[23]||(l[23]=t(" 校對：",-1)),n(o,{href:"https://github.com/wxy"},{default:r(()=>[...l[19]||(l[19]=[t("wxy",-1)])]),_:1})]),i("p",null,[l[26]||(l[26]=t("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...l[24]||(l[24]=[t("LCTT",-1)])]),_:1}),l[27]||(l[27]=t(" 原創編譯，",-1)),n(o,{href:"https://linux.cn/"},{default:r(()=>[...l[25]||(l[25]=[t("Linux中國",-1)])]),_:1}),l[28]||(l[28]=t(" 榮譽推出",-1))])])}const P=a(d,[["render",f]]);export{C as __pageData,P as default};
